#!/usr/bin/env python3
# Coverage: formData successful controls and DOM order -> formDataCase() -> exact ordered key/value list.
# Coverage: disabled controls and disabled fieldset inheritance -> formDataCase() -> excluded rows.
# Coverage: checkbox/radio checked rules and empty value=on -> formDataCase() -> exact values.
# Coverage: select multiple and single fallback -> formDataCase() -> all selected and first enabled option.
# Coverage: textarea/input val() -> formDataCase() -> exact values.
# Coverage: submit method/action/reuse and action validation boundary -> submitCase() -> request URL, method, data and IllegalArgumentException.
# Coverage: DOM re-query plus addElement/elements dynamic -> dynamicCase() -> before/after lists.
# Counterexamples: a bare <button> or disabled row returned fails the exact list; first-option-any fails fallback; cached lists fail dynamicCase(); wrong checked/default values fail checkbox rows; wrong GET/POST or request data fails submitCase(); URL validation in formData fails the action boundary.
import os
import sys
import tempfile
import subprocess
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

JAVA = r'''
import java.util.List;
import org.jsoup.Connection;
import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.FormElement;

public class FormAcceptanceHarness {
    private static int failures = 0;
    private static final String NL = String.valueOf((char) 10);

    private static void check(boolean ok, String label, String detail) {
        System.out.println((ok ? "OK " : "FAIL ") + label + " " + detail);
        if (!ok) failures++;
    }

    private static void checkEq(String expected, String actual, String label) {
        check(expected.equals(actual), label, "expected=[" + expected + "] actual=[" + actual + "]");
    }

    private static String render(List<Connection.KeyVal> data) {
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < data.size(); i++) {
            if (i > 0) out.append((char) 10);
            Connection.KeyVal item = data.get(i);
            out.append(item.key()).append('=').append(item.value());
        }
        return out.toString();
    }

    private static FormElement form(String html, String baseUri) {
        Document doc = baseUri == null ? Jsoup.parse(html) : Jsoup.parse(html, baseUri);
        Element selected = doc.selectFirst("form");
        if (!(selected instanceof FormElement)) throw new IllegalStateException("form element not found");
        return (FormElement) selected;
    }

    private static void formDataCase() {
        String html = "<form>"
            + "<input name=first value=one>"
            + "<input value=noname>"
            + "<input name=disabled-direct value=skip disabled>"
            + "<fieldset disabled>"
            + "<input name=fieldset-input value=skip>"
            + "<select name=fieldset-select><option value=skip selected></select>"
            + "<textarea name=fieldset-text>skip</textarea>"
            + "</fieldset>"
            + "<fieldset><input name=fieldset-ok value=field ok></fieldset>"
            + "<select name=multi multiple>"
            + "<option value=m1 selected><option value=m2><option value=m3 selected>"
            + "<option value=m4 selected disabled></select>"
            + "<select name=single><option value=s0 disabled><option value=s1><option value=s2 selected></select>"
            + "<select name=fallback><option value=f0 disabled><option value=f1><option value=f2></select>"
            + "<input type=checkbox name=cb1 checked>"
            + "<input type=checkbox name=cb2 value= checked>"
            + "<input type=checkbox name=cb3 value=off checked>"
            + "<input type=checkbox name=cb4 value=skip>"
            + "<input type=radio name=radio value=r1>"
            + "<input type=radio name=radio value=r2 checked>"
            + "<input type=radio name=radio value=r3 checked disabled>"
            + "<textarea name=ta>textarea value</textarea>"

