import org.jsoup.internal.ControllableInputStream;
import org.jsoup.Progress;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.*;

public class MismatchTest {
    static String run(int declared, int actual) throws IOException {
        byte[] data = new byte[actual];
        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(data), 0);
        List<String> ev = new ArrayList<>();
        in.onProgress(declared, (p, t, pct, ctx) -> ev.add(p + "/" + t + "/" + pct), in);
        byte[] buf = new byte[1024];
        while (in.read(buf) != -1) {}
        return ev.toString();
    }
    public static void main(String[] a) throws Exception {
        System.out.println("under-deliver: " + run(10000, 5000));
        System.out.println("over-deliver:  " + run(5000, 8000));
        System.out.println("unknown:       " + run(-1, 5000));
        System.out.println("exact:         " + run(5000, 5000));

        // handler throws repeatedly; must keep getting events and still see completion
        byte[] data = new byte[3000];
        ControllableInputStream in = ControllableInputStream.wrap(new ByteArrayInputStream(data), 0);
        AtomicInteger calls = new AtomicInteger();
        in.onProgress(-1, (p, t, pct, ctx) -> { calls.incrementAndGet(); throw new IllegalStateException("x"); }, in);
        byte[] buf = new byte[1024];
        int total = 0, r;
        while ((r = in.read(buf)) != -1) total += r;
        System.out.println("thrower calls=" + calls + " delivered=" + total);
    }
}
